class PanelQuad;

struct vector4d {
    float x, y, z, w;
};

struct matrix4x4 {
    vector4d x __attribute__((aligned(16)));
    vector4d y, z, w;
};

static inline matrix4x4 operator*(const matrix4x4 &a, const matrix4x4 &b)
{
    matrix4x4 local;
    asm(
        "lqc2 vf1,0x0(%2)\n"
        "lqc2 vf2,0x10(%2)\n"
        "lqc2 vf3,0x20(%2)\n"
        "lqc2 vf4,0x30(%2)\n"
        "lqc2 vf5,0x0(%1)\n"
        "lqc2 vf6,0x10(%1)\n"
        "lqc2 vf7,0x20(%1)\n"
        "lqc2 vf8,0x30(%1)\n"
        "vmulax.xyzw ACC,vf1,vf5\n"
        "vmadday.xyzw ACC,vf2,vf5\n"
        "vmaddaz.xyzw ACC,vf3,vf5\n"
        "vmaddw.xyzw vf9,vf4,vf5\n"
        "vmulax.xyzw ACC,vf1,vf6\n"
        "vmadday.xyzw ACC,vf2,vf6\n"
        "vmaddaz.xyzw ACC,vf3,vf6\n"
        "vmaddw.xyzw vf10,vf4,vf6\n"
        "vmulax.xyzw ACC,vf1,vf7\n"
        "vmadday.xyzw ACC,vf2,vf7\n"
        "vmaddaz.xyzw ACC,vf3,vf7\n"
        "vmaddw.xyzw vf11,vf4,vf7\n"
        "vmulax.xyzw ACC,vf1,vf8\n"
        "vmadday.xyzw ACC,vf2,vf8\n"
        "vmaddaz.xyzw ACC,vf3,vf8\n"
        "vmaddw.xyzw vf12,vf4,vf8\n"
        "sqc2 vf9,0x0(%0)\n"
        "sqc2 vf10,0x10(%0)\n"
        "sqc2 vf11,0x20(%0)\n"
        "sqc2 vf12,0x30(%0)\n"
        :
        : "r" (&local.x.x), "r" (&a.x.x), "r" (&b.x.x)
    );
    return local;
}

struct panel_vtable {
    char padding[64];
    short adjustment;
    short reserved;
    void (*init)(void *, PanelQuad **, matrix4x4, bool);
};

struct PanelGeom {
    char padding[16];
    matrix4x4 matrix;
    char padding2[28];
    PanelGeom *children;
    char padding3[8];
    panel_vtable *vtable;

    void Init(PanelQuad **pquads, matrix4x4 parent_matrix, bool floating);
};

void PanelGeom::Init(PanelQuad **pquads, matrix4x4 parent_matrix, bool floating)
{
    matrix4x4 this_matrix = parent_matrix*matrix;
    if(children) children->Init(pquads, this_matrix, floating);
}
